API Gateway & Load Balancer.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway_load_balancer, "API Gateway & Load Balancer") {
    Component(Amazon_Route_53, "Amazon Route 53", "AWS DNS", "Handles latency-based DNS routing for global traffic distribution.")
    Component(AWS_WAF, "AWS WAF", "AWS Web Application Firewall", "Protects against web exploits and malicious traffic.")
    Component(Application_Load_Balancer, "Application Load Balancer", "AWS ALB", "Distributes incoming HTTP/HTTPS traffic across multiple targets.")
    Component(API_Gateway, "API Gateway", "AWS API Gateway", "Manages secure client requests and real-time streams via HTTPS/REST and WebSockets.")
}

Rel(Amazon_Route_53, AWS_WAF, "Routes filtered traffic to")
Rel(AWS_WAF, Application_Load_Balancer, "Forwards inspected traffic to")
Rel(Application_Load_Balancer, API_Gateway, "Routes client requests to")

@enduml

Checkout & Order Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("checkout_order_service", "Checkout & Order Service") {
    Component("Checkout Orchestrator", "Checkout Orchestrator", "Go SDK, Temporal", "Manages multi-step saga state persistence and timeout workflows for orders.")
    Component("Order Management API", "Order Management API", "REST, gRPC", "Exposes endpoints for creating and managing customer orders.")
    Component("Fulfillment & Integration Engine", "Fulfillment & Integration Engine", "Node.js / Go / Python", "Ingests third-party webhooks and queues asynchronous fulfillment updates.")
    Component("Data Access Repository", "Data Access Repository", "SQL / ORM", "Handles data persistence operations for orders, refunds, and idempotency data.")
}

Rel("Checkout Orchestrator", "Data Access Repository", "Persists workflow state and transaction data")
Rel("Order Management API", "Checkout Orchestrator", "Triggers checkout saga execution")
Rel("Fulfillment & Integration Engine", "Checkout Orchestrator", "Updates order fulfillment status")

@enduml
